from pathlib import Path
import csv,json,numpy as np
root=Path('mhd_llm/codex');obs=root/'observations'
def read(p,sep='\t'):return np.genfromtxt(p,names=True,delimiter=sep,dtype=None,encoding='utf8')
c=read(obs/'ephemeris_comet.tsv');e=read(obs/'ephemeris_wind.tsv');g=read(obs/'xmm_gtis.tsv');g=g[g['detector']=='pn'];s=json.load(open(root/'results/summary.json'));case=s['reference_case'];a=read(root/f'results/{case}/probe.csv',',');a=a[a['probe_id']==0]
t0=np.mean([g['start_mjd_utc'].min(),g['stop_mjd_utc'].max()]);ce=np.array([np.interp(t0,c['mjd_utc'],c[k]) for k in ['x_au','y_au','z_au']]);ee=np.array([np.interp(t0,e['mjd_utc'],e[k]) for k in ['x_au','y_au','z_au']]);tau=float(np.linalg.norm(ce-ee)*149597870700/299792458);dt=tau/86400
comparisons={}
for col in ['n_cm3','speed_kms','flux_cm2_s']:
 totals=[]
 for lag in [0,dt]:
  value=0;duration=0
  for start,stop in zip(g['start_mjd_utc']-60980-lag,g['stop_mjd_utc']-60980-lag):
   knots=np.r_[start,a['day'][(a['day']>start)&(a['day']<stop)],stop]
   value+=np.trapezoid(np.interp(knots,a['day'],a[col]),knots);duration+=stop-start
  totals.append(value/duration)
 comparisons[col]={'simultaneous_UTC_mean':totals[0],'photon_emission_time_mean':totals[1],'relative_change':totals[1]/totals[0]-1}
report={'case':case,'geometric_earth_comet_distance_au':float(np.linalg.norm(ce-ee)),'light_travel_seconds':tau,'mean_shift_comparison':comparisons,'interpretation':'Observer arrival UTC versus comet emission-time difference is about15.65minutes; present smooth mean density/flux changes below1percent. Not a dominant current uncertainty.'}
(obs/'light_travel_time_audit.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(report,indent=2))
PY","max_output_tokens":3000}));

